import { Flashcard } from "../types";

const source = "Scioly.org Designer Genes / Heredity wiki";
const expansionSource = "Scioly.org Designer Genes / Heredity wiki; OpenStax Biology 2e; Campbell Biology";

export const DESIGNER_GENES_DECK: Flashcard[] = [
  { id: "dg-1", category: "Inheritance", front: "Genotype vs. phenotype", back: "Genotype is an organism's allele combination. Phenotype is the observable trait produced by genotype and environment.", source },
  { id: "dg-2", category: "Inheritance", front: "Homozygous vs. heterozygous", back: "Homozygous means two matching alleles; heterozygous means two different alleles at a locus.", source },
  { id: "dg-3", category: "Inheritance", front: "Law of segregation", back: "The two alleles for a gene separate during gamete formation, so each gamete receives one allele.", source },
  { id: "dg-4", category: "Inheritance", front: "Law of independent assortment", back: "Allele pairs for different genes assort independently during meiosis when the genes are unlinked or sufficiently far apart.", source },
  { id: "dg-5", category: "Inheritance", front: "Aa × Aa genotypic and phenotypic ratios", back: "Genotypes: 1 AA : 2 Aa : 1 aa. With complete dominance, phenotypes: 3 dominant : 1 recessive.", source },
  { id: "dg-6", category: "Inheritance", front: "AA × aa offspring", back: "All offspring are Aa and show the dominant phenotype under complete dominance.", source },
  { id: "dg-7", category: "Inheritance", front: "Aa × aa offspring", back: "Half are Aa and half are aa; the phenotype ratio is 1 dominant : 1 recessive under complete dominance.", source },
  { id: "dg-8", category: "Inheritance", front: "What is a testcross?", back: "Crossing an individual with a dominant phenotype to a homozygous recessive individual to infer the unknown genotype.", source },
  { id: "dg-9", category: "Inheritance", front: "What is a dihybrid cross?", back: "A cross tracking two genes or traits, such as AaBb × AaBb.", source },
  { id: "dg-10", category: "Inheritance", front: "AaBb × AaBb phenotypic ratio", back: "With independent assortment and complete dominance, the classic ratio is 9:3:3:1.", source },
  { id: "dg-11", category: "Inheritance", front: "How many gamete types can AaBbCc produce?", back: "2^3 = 8, assuming the genes assort independently; each gene contributes two possible alleles.", source },
  { id: "dg-12", category: "Inheritance", front: "Product rule in genetics", back: "For independent events occurring together, multiply their probabilities.", source },
  { id: "dg-13", category: "Inheritance", front: "Sum rule in genetics", back: "For mutually exclusive ways an outcome can occur, add their probabilities.", source },
  { id: "dg-14", category: "Inheritance", front: "Incomplete dominance", back: "The heterozygote has an intermediate phenotype between the two homozygotes; a typical cross gives a 1:2:1 phenotypic ratio.", source },
  { id: "dg-15", category: "Inheritance", front: "Codominance", back: "Both alleles are visibly expressed in the heterozygote, such as both red and white patches in roan cattle.", source },
  { id: "dg-16", category: "Inheritance", front: "Multiple alleles", back: "A population has more than two allele forms for a gene, although an individual still normally carries only two.", source },
  { id: "dg-17", category: "Inheritance", front: "ABO blood type alleles", back: "IA and IB are codominant; i is recessive. IAIB produces type AB, while ii produces type O.", source },
  { id: "dg-18", category: "Inheritance", front: "What is epistasis?", back: "One gene masks or modifies the expression of another, non-allelic gene.", source },
  { id: "dg-19", category: "Inheritance", front: "Common recessive epistasis ratio", back: "A 9:3:4 ratio can result when a homozygous recessive genotype at one locus masks another gene.", source },
  { id: "dg-20", category: "Inheritance", front: "What is a lethal allele?", back: "An allele or genotype that causes death, often before reproduction, altering the expected surviving offspring ratio.", source },
  { id: "dg-21", category: "Inheritance", front: "What is a sex-linked trait?", back: "A trait controlled by a gene on a sex chromosome, commonly the X chromosome.", source },
  { id: "dg-22", category: "Inheritance", front: "Why are X-linked recessive traits more common in males?", back: "Males have one X chromosome, so one recessive allele can be expressed; females generally need two copies.", source },
  { id: "dg-23", category: "Inheritance", front: "X-linked recessive carrier mother × unaffected father", back: "Each son has a 50% chance of being affected; each daughter has a 50% chance of being a carrier, assuming the father is unaffected.", source },
  { id: "dg-24", category: "Inheritance", front: "Y-linked inheritance pattern", back: "A Y-linked trait passes from an affected father to all sons and to no daughters.", source },
  { id: "dg-25", category: "Inheritance", front: "What does a pedigree square represent?", back: "Conventionally, a square represents a male and a circle represents a female; shading usually indicates the trait.", source },
  { id: "dg-26", category: "Inheritance", front: "Pedigree clue for autosomal dominant inheritance", back: "The trait often appears in every generation and affected people usually have an affected parent, with males and females similarly affected.", source },
  { id: "dg-27", category: "Inheritance", front: "Pedigree clue for autosomal recessive inheritance", back: "Unaffected parents can have an affected child; the trait may skip generations and affects males and females similarly.", source },
  { id: "dg-28", category: "Inheritance", front: "Pedigree clue for X-linked recessive inheritance", back: "More males may be affected, affected sons can have unaffected fathers, and carrier mothers can pass the allele to sons.", source },
  { id: "dg-29", category: "Inheritance", front: "Linked vs. unlinked genes", back: "Linked genes are on the same chromosome and tend to be inherited together; unlinked genes assort independently.", source },
  { id: "dg-30", category: "Inheritance", front: "What is a recombinant offspring?", back: "An offspring with an allele combination different from either parental combination, often produced by crossing over.", source },
  { id: "dg-31", category: "DNA", front: "What are the three parts of a DNA nucleotide?", back: "A phosphate group, a deoxyribose sugar, and a nitrogenous base.", source },
  { id: "dg-32", category: "DNA", front: "DNA purines and pyrimidines", back: "Purines have two rings: adenine and guanine. Pyrimidines have one ring: cytosine and thymine.", source },
  { id: "dg-33", category: "DNA", front: "DNA base-pairing rules", back: "Adenine pairs with thymine; guanine pairs with cytosine through hydrogen bonds.", source },
  { id: "dg-34", category: "DNA", front: "Chargaff's rules", back: "In double-stranded DNA, A = T and G = C; total purines equal total pyrimidines.", source },
  { id: "dg-35", category: "DNA", front: "5' and 3' DNA direction", back: "DNA strands are antiparallel. New DNA is synthesized 5' to 3' by adding nucleotides to a free 3' OH.", source },
  { id: "dg-36", category: "DNA", front: "Nucleoside vs. nucleotide", back: "A nucleoside is sugar plus base. A nucleotide is nucleoside plus one or more phosphate groups.", source },
  { id: "dg-37", category: "DNA", front: "What is chromatin?", back: "DNA associated with histone proteins and other molecules; it packages DNA and helps regulate access to genes.", source },
  { id: "dg-38", category: "DNA", front: "Euchromatin vs. heterochromatin", back: "Euchromatin is relatively open and transcriptionally active; heterochromatin is compact and generally less active.", source },
  { id: "dg-39", category: "DNA", front: "Semiconservative DNA replication", back: "Each daughter DNA molecule contains one original strand and one newly synthesized strand.", source },
  { id: "dg-40", category: "DNA", front: "What does helicase do?", back: "Unwinds the DNA double helix and separates the strands at the replication fork.", source },
  { id: "dg-41", category: "DNA", front: "What does primase do?", back: "Synthesizes a short RNA primer that provides the free 3' OH needed by DNA polymerase.", source },
  { id: "dg-42", category: "DNA", front: "What does DNA polymerase do?", back: "Adds complementary DNA nucleotides to a growing strand in the 5' to 3' direction and may proofread.", source },
  { id: "dg-43", category: "DNA", front: "Leading vs. lagging strand", back: "The leading strand is made continuously toward the fork; the lagging strand is made discontinuously away from the fork.", source },
  { id: "dg-44", category: "DNA", front: "What are Okazaki fragments?", back: "Short DNA segments synthesized on the lagging strand and later joined by DNA ligase.", source },
  { id: "dg-45", category: "DNA", front: "What does DNA ligase do?", back: "Seals breaks in the sugar-phosphate backbone, including between Okazaki fragments.", source },
  { id: "dg-46", category: "DNA", front: "What is a telomere?", back: "A repetitive chromosome-end sequence that protects chromosome ends and shortens during many rounds of replication.", source },
  { id: "dg-47", category: "DNA", front: "What is a centromere?", back: "A chromosome region where sister chromatids are joined and kinetochores form for spindle attachment.", source },
  { id: "dg-48", category: "DNA", front: "What is a mutation?", back: "A change in genetic material; effects range from neutral to harmful or beneficial depending on context.", source },
  { id: "dg-49", category: "DNA", front: "Transition vs. transversion mutation", back: "A transition swaps purine for purine or pyrimidine for pyrimidine. A transversion swaps a purine and a pyrimidine.", source },
  { id: "dg-50", category: "DNA", front: "Silent, missense, and nonsense mutations", back: "Silent leaves the amino acid unchanged; missense changes an amino acid; nonsense creates a premature stop codon.", source },
  { id: "dg-51", category: "DNA", front: "Frameshift mutation", back: "An insertion or deletion not in a multiple of three shifts the reading frame and changes downstream codons.", source },
  { id: "dg-52", category: "RNA", front: "DNA vs. RNA", back: "DNA usually has deoxyribose, thymine, and two strands. RNA usually has ribose, uracil, and one strand.", source },
  { id: "dg-53", category: "RNA", front: "What is transcription?", back: "The synthesis of an RNA molecule using a DNA template, generally by RNA polymerase.", source },
  { id: "dg-54", category: "RNA", front: "What is translation?", back: "Ribosomes use an mRNA sequence to assemble a polypeptide from amino acids.", source },
  { id: "dg-55", category: "RNA", front: "mRNA, tRNA, and rRNA roles", back: "mRNA carries coding information; tRNA brings amino acids and matches codons; rRNA forms much of the ribosome and catalyzes peptide-bond formation.", source },
  { id: "dg-56", category: "RNA", front: "What is a promoter?", back: "A DNA region where transcription machinery binds to begin transcription of a gene.", source },
  { id: "dg-57", category: "RNA", front: "What is a codon?", back: "A three-nucleotide mRNA sequence that specifies an amino acid or stop signal.", source },
  { id: "dg-58", category: "RNA", front: "Start and stop codons", back: "AUG commonly starts translation and codes for methionine. UAA, UAG, and UGA are stop codons.", source },
  { id: "dg-59", category: "RNA", front: "What is the central dogma?", back: "Information generally flows from DNA to RNA to protein, with important biological exceptions such as reverse transcription.", source },
  { id: "dg-60", category: "RNA", front: "What happens to eukaryotic pre-mRNA?", back: "It receives a 5' cap, a 3' poly-A tail, and intron removal through splicing before mature mRNA is translated.", source },
  { id: "dg-61", category: "RNA", front: "Introns vs. exons", back: "Introns are removed from pre-mRNA; exons remain in mature mRNA and may contribute to the coding or untranslated regions.", source },
  { id: "dg-62", category: "RNA", front: "What is alternative splicing?", back: "Different exon combinations are joined from one primary transcript, allowing one gene to produce multiple RNA and protein products.", source },
  { id: "dg-63", category: "RNA", front: "What is microRNA?", back: "A small regulatory RNA that binds complementary mRNA sequences to reduce translation or promote mRNA degradation.", source },
  { id: "dg-64", category: "Cell Division", front: "Mitosis vs. meiosis", back: "Mitosis produces two genetically similar diploid cells. Meiosis produces four genetically varied haploid cells.", source },
  { id: "dg-65", category: "Cell Division", front: "What is the purpose of mitosis?", back: "Growth, tissue repair, replacement of cells, and asexual reproduction in some organisms.", source },
  { id: "dg-66", category: "Cell Division", front: "What is the purpose of meiosis?", back: "Producing haploid gametes and increasing genetic variation for sexual reproduction.", source },
  { id: "dg-67", category: "Cell Division", front: "Mitosis phases in order", back: "Prophase, metaphase, anaphase, telophase, followed by cytokinesis; remember PMAT.", source },
  { id: "dg-68", category: "Cell Division", front: "What separates in mitotic anaphase?", back: "Sister chromatids separate and move to opposite poles.", source },
  { id: "dg-69", category: "Cell Division", front: "What separates in meiosis I?", back: "Homologous chromosomes separate; sister chromatids remain together.", source },
  { id: "dg-70", category: "Cell Division", front: "What separates in meiosis II?", back: "Sister chromatids separate, similar to mitosis.", source },
  { id: "dg-71", category: "Cell Division", front: "What is crossing over?", back: "Exchange of corresponding DNA segments between nonsister chromatids of homologous chromosomes during prophase I.", source },
  { id: "dg-72", category: "Cell Division", front: "What is independent assortment in meiosis?", back: "Random orientation of homologous pairs at metaphase I creates different maternal and paternal chromosome combinations.", source },
  { id: "dg-73", category: "Cell Division", front: "What is nondisjunction?", back: "Failure of homologous chromosomes or sister chromatids to separate, producing gametes with abnormal chromosome numbers.", source },
  { id: "dg-74", category: "Cell Division", front: "What is aneuploidy?", back: "An abnormal number of particular chromosomes, such as trisomy or monosomy.", source },
  { id: "dg-75", category: "DNA Repair", front: "What causes DNA damage?", back: "Replication errors, spontaneous chemical changes, reactive molecules, radiation, UV light, and environmental mutagens.", source },
  { id: "dg-76", category: "DNA Repair", front: "What is direct reversal repair?", back: "Repair that chemically reverses damage without removing the damaged base or nucleotide, such as photoreactivation of some pyrimidine dimers.", source },
  { id: "dg-77", category: "DNA Repair", front: "What is base excision repair?", back: "A glycosylase removes one damaged base; the backbone is processed and DNA polymerase fills the correct nucleotide.", source },
  { id: "dg-78", category: "DNA Repair", front: "What is nucleotide excision repair?", back: "A larger damaged stretch is recognized and excised, then DNA polymerase resynthesizes the missing region and ligase seals it.", source },
  { id: "dg-79", category: "DNA Repair", front: "What is mismatch repair?", back: "Repair of incorrectly paired bases left after replication by identifying the newly synthesized strand and replacing the mismatch.", source },
  { id: "dg-80", category: "DNA Repair", front: "What is translesion synthesis?", back: "A specialized polymerase replicates across a lesion; it allows replication to continue but can be error-prone.", source },
  { id: "dg-81", category: "Gene Expression", front: "What is an operon?", back: "A group of prokaryotic genes controlled by a common promoter and transcribed together as one RNA.", source },
  { id: "dg-82", category: "Gene Expression", front: "Inducible vs. repressible operon", back: "An inducible operon is usually off and activated when needed; a repressible operon is usually on and shut off when its product is abundant.", source },
  { id: "dg-83", category: "Gene Expression", front: "How does the lac operon respond to lactose?", back: "Allolactose binds the repressor and reduces its binding to the operator, allowing transcription of lactose-use genes.", source },
  { id: "dg-84", category: "Gene Expression", front: "How does the trp operon respond to tryptophan?", back: "Tryptophan acts as a corepressor; when abundant, it helps the repressor shut off genes for tryptophan synthesis.", source },
  { id: "dg-85", category: "Gene Expression", front: "What is an operator?", back: "A regulatory DNA site in an operon where a repressor can bind and affect transcription.", source },
  { id: "dg-86", category: "Gene Expression", front: "What is epigenetics?", back: "Heritable or stable changes in gene expression that do not change the DNA base sequence.", source },
  { id: "dg-87", category: "Gene Expression", front: "DNA methylation generally does what?", back: "Methyl groups at regulatory regions often reduce transcription by making DNA less accessible or recruiting repressing proteins.", source },
  { id: "dg-88", category: "Gene Expression", front: "Histone acetylation generally does what?", back: "It often loosens chromatin and makes transcription more accessible, though context and specific marks matter.", source },
  { id: "dg-89", category: "Gene Expression", front: "What is a transcription factor?", back: "A protein that binds regulatory DNA and increases or decreases transcription of target genes.", source },
  { id: "dg-90", category: "Gene Expression", front: "What is post-translational modification?", back: "Chemical or enzymatic processing of a protein after translation, such as phosphorylation, glycosylation, lipidation, or cleavage.", source },
  { id: "dg-91", category: "Gene Expression", front: "What do chaperonins do?", back: "They assist newly made proteins in folding correctly and can help prevent harmful aggregation.", source },
  { id: "dg-92", category: "Gene Expression", front: "What is epistasis vs. dominance?", back: "Epistasis is interaction between different genes; dominance is interaction between alleles of the same gene.", source },
  { id: "dg-93", category: "Population Genetics", front: "Hardy-Weinberg assumptions", back: "No mutation, no migration/gene flow, very large population, no natural selection, and random mating.", source },
  { id: "dg-94", category: "Population Genetics", front: "Hardy-Weinberg equations", back: "p + q = 1 for allele frequencies; p² + 2pq + q² = 1 for genotype frequencies.", source },
  { id: "dg-95", category: "Population Genetics", front: "What do p and q represent?", back: "The frequencies of two alleles at a locus, usually the dominant and recessive allele, with p + q = 1.", source },
  { id: "dg-96", category: "Population Genetics", front: "What do p², 2pq, and q² represent?", back: "Expected frequencies of homozygous dominant, heterozygous, and homozygous recessive genotypes.", source },
  { id: "dg-97", category: "Population Genetics", front: "Hardy-Weinberg calculation: q² = 0.36", back: "q = 0.6, p = 0.4, p² = 0.16, and 2pq = 0.48.", source },
  { id: "dg-98", category: "Population Genetics", front: "What is genetic drift?", back: "Random change in allele frequencies, strongest in small populations and especially after bottlenecks or founder events.", source },
  { id: "dg-99", category: "Population Genetics", front: "What is the founder effect?", back: "Genetic drift caused when a new population is started by a small, nonrepresentative sample of a source population.", source },
  { id: "dg-100", category: "Population Genetics", front: "What is a bottleneck effect?", back: "A sharp reduction in population size that randomly changes allele frequencies and reduces genetic variation.", source },
  { id: "dg-101", category: "Population Genetics", front: "What is gene flow?", back: "Movement of alleles between populations through migration and reproduction.", source },
  { id: "dg-102", category: "Population Genetics", front: "How does natural selection affect allele frequencies?", back: "Alleles associated with greater reproductive success tend to increase in frequency across generations.", source },
  { id: "dg-103", category: "Evolution", front: "What is a phylogenetic tree?", back: "A diagram representing hypothesized evolutionary relationships among organisms or sequences.", source },
  { id: "dg-104", category: "Evolution", front: "What does a node represent on a phylogenetic tree?", back: "A common ancestor or branching event.", source },
  { id: "dg-105", category: "Evolution", front: "What do sister taxa represent?", back: "Two lineages that share an immediate common ancestor and are each other’s closest relatives on the tree.", source },
  { id: "dg-106", category: "Evolution", front: "What is a clade?", back: "An ancestor and all of its descendants, forming a complete branch of a phylogenetic tree.", source },
  { id: "dg-107", category: "Evolution", front: "What is homology?", back: "Similarity due to shared ancestry, even if the structures or sequences now have different functions.", source },
  { id: "dg-108", category: "Evolution", front: "What is convergent evolution?", back: "Independent evolution of similar traits in unrelated lineages due to similar selective pressures.", source },
  { id: "dg-109", category: "Biotechnology", front: "What is PCR?", back: "Polymerase chain reaction, a method that exponentially amplifies a selected DNA region through repeated denaturation, primer annealing, and extension.", source },
  { id: "dg-110", category: "Biotechnology", front: "What are PCR primers?", back: "Short DNA sequences complementary to opposite strands that define the region to be amplified.", source },
  { id: "dg-111", category: "Biotechnology", front: "What is gel electrophoresis?", back: "A method that separates charged DNA fragments by movement through a gel in an electric field; smaller fragments generally travel farther.", source },
  { id: "dg-112", category: "Biotechnology", front: "What is a restriction enzyme?", back: "An enzyme that recognizes a specific DNA sequence and cuts the DNA at or near that site.", source },
  { id: "dg-113", category: "Biotechnology", front: "Sticky vs. blunt ends", back: "Sticky ends have short single-stranded overhangs that can base-pair; blunt ends have no overhang.", source },
  { id: "dg-114", category: "Biotechnology", front: "What is a plasmid?", back: "A small, usually circular DNA molecule in bacteria that replicates independently and can serve as a cloning vector.", source },
  { id: "dg-115", category: "Biotechnology", front: "What is recombinant DNA?", back: "DNA constructed by joining genetic material from different sources or molecules.", source },
  { id: "dg-116", category: "Biotechnology", front: "What is a cloning vector?", back: "A DNA carrier, such as a plasmid or viral vector, used to replicate or deliver an inserted sequence.", source },
  { id: "dg-117", category: "Biotechnology", front: "What does CRISPR-Cas9 do?", back: "A guide RNA directs Cas9 to a complementary DNA sequence, where Cas9 makes a targeted cut that can be repaired to edit the gene.", source },
  { id: "dg-118", category: "Biotechnology", front: "What is DNA sequencing?", back: "Determining the order of nucleotides in a DNA molecule or region.", source },
  { id: "dg-119", category: "Biotechnology", front: "What is a SNP?", back: "A single-nucleotide polymorphism: a common one-base variation at a specific genomic position.", source },
  { id: "dg-120", category: "Biotechnology", front: "What is a transgenic organism?", back: "An organism whose genome contains a gene or sequence introduced from another species or source.", source },
  { id: "dg-121", category: "Question Marathon", front: "What happens during nondisjunction?", back: "Homologous chromosomes or sister chromatids fail to separate, producing gametes with too many or too few chromosomes.", source: "Designer Genes Question Marathon" },
  { id: "dg-122", category: "Question Marathon", front: "What is aneuploidy? Give two examples.", back: "A gain or loss of individual chromosomes; examples include trisomy 21 and XXY (Klinefelter syndrome).", source: "Designer Genes Question Marathon" },
  { id: "dg-123", category: "Question Marathon", front: "What are DNA strands made of?", back: "Nucleotides, each containing a phosphate group, a deoxyribose sugar, and a nitrogenous base; the strands are antiparallel and paired by hydrogen bonds.", source: "Designer Genes Question Marathon" },
  { id: "dg-124", category: "Question Marathon", front: "What information is needed before solving a dihybrid cross?", back: "The parental genotypes, allele relationships, and whether the genes assort independently or are linked.", source: "Designer Genes Question Marathon" },
  { id: "dg-125", category: "Question Marathon", front: "What is the expected result of a heterozygous incomplete-dominance cross?", back: "Aa × Aa gives 1 homozygote for one phenotype : 2 heterozygotes with the intermediate phenotype : 1 homozygote for the other phenotype.", source: "Designer Genes Question Marathon" },
  { id: "dg-126", category: "Question Marathon", front: "How do you approach a multi-trait genetics problem?", back: "Identify each gene and allele relationship, determine gametes, build or factor the cross, calculate genotype and phenotype probabilities, then check that totals sum to 1.", source: "Designer Genes Question Marathon" },
  { id: "dg-127", category: "Question Marathon", front: "What should you look for in gel electrophoresis data?", back: "Band positions, lane labels, a DNA ladder, controls, and whether samples share fragment sizes or a matching pattern.", source: "Designer Genes Question Marathon" },
  { id: "dg-128", category: "Question Marathon", front: "How does gel electrophoresis separate DNA?", back: "DNA moves toward the positive electrode because of its negative charge; smaller fragments migrate faster and farther through the gel.", source: "Designer Genes Question Marathon" },
  { id: "dg-129", category: "Question Marathon", front: "Why can a band pattern identify a DNA sample?", back: "A restriction digest or amplification produces a pattern of fragment sizes that can be compared with known samples or controls.", source: "Designer Genes Question Marathon" },
  { id: "dg-130", category: "Question Marathon", front: "What is a restriction digest?", back: "Cutting DNA with restriction enzymes that recognize specific sequences, producing fragments whose sizes can be analyzed.", source: "Designer Genes Question Marathon" },
  { id: "dg-131", category: "Question Marathon", front: "What does a DNA ladder do in gel electrophoresis?", back: "It provides fragments of known sizes so the approximate sizes of sample bands can be estimated.", source: "Designer Genes Question Marathon" },
  { id: "dg-132", category: "Question Marathon", front: "What controls help interpret biotechnology data?", back: "A positive control should produce the expected signal, while a negative control should not; failed controls make sample conclusions unreliable.", source: "Designer Genes Question Marathon" },
  { id: "dg-133", category: "Question Marathon", front: "How can you distinguish a technical failure from a negative result?", back: "Check whether the positive control, loading control, amplification control, and other expected signals worked before interpreting a missing sample signal.", source: "Designer Genes Question Marathon" },
  { id: "dg-134", category: "Question Marathon", front: "What kind of practice was recommended in the Designer Genes forums?", back: "Use the current rules, the Designer Genes/Heredity wiki, previous tests and test exchanges, and a genetics textbook such as Campbell Biology.", source: "Designer Genes forum discussion" },
  { id: "dg-135", category: "Question Marathon", front: "Are outside reference materials automatically allowed at competition?", back: "Do not assume so; permitted resources are determined by the current official rules. Older forum discussions specifically warn that rules can differ by season.", source: "Designer Genes forum discussion" },
  { id: "dg-136", category: "Question Marathon", front: "When should you begin practice tests?", back: "After learning the core material, begin early enough to identify weak topics, then use timed tests and error review before competition.", source: "Designer Genes forum discussion" },
  { id: "dg-137", category: "Question Marathon", front: "What did a forum discussion identify as a potentially important mutation focus?", back: "The molecular consequences of mutations, including mutation types and causes, were discussed as likely study material.", source: "Designer Genes forum discussion" },
  { id: "dg-138", category: "Question Marathon", front: "What is a molecular consequence of a nonsense mutation?", back: "A premature stop codon can truncate the protein and often eliminate or greatly reduce its function.", source: "Designer Genes forum discussion" },
  { id: "dg-139", category: "Question Marathon", front: "What is the probability of attached earlobes if both parents are homozygous recessive?", back: "100%, assuming attached earlobes are recessive and the trait model is valid.", source: "Designer Genes Question Marathon" },
  { id: "dg-140", category: "Question Marathon", front: "For Aa × Aa, what is the probability of a recessive phenotype?", back: "25% or 1/4 under complete dominance, because only aa expresses the recessive phenotype.", source: "Designer Genes Question Marathon" },
  { id: "dg-141", category: "Question Marathon", front: "How do you solve a cross with two independent traits?", back: "Solve each monohybrid probability separately and multiply the probabilities for the requested combined phenotype.", source: "Designer Genes Question Marathon" },
  { id: "dg-142", category: "Question Marathon", front: "What is a common mistake in pedigree questions?", back: "Assuming an inheritance pattern from one individual or ignoring unaffected parents, sex distribution, carriers, and whether the pedigree marks carriers.", source: "Designer Genes Question Marathon" },
  { id: "dg-143", category: "Question Marathon", front: "What is a common mistake in reading DNA sequence questions?", back: "Forgetting which strand is the template, reversing 5' and 3' direction, or using DNA bases instead of RNA bases during transcription.", source: "Designer Genes Question Marathon" },
  { id: "dg-144", category: "Question Marathon", front: "What does ‘molecular biology of inheritance’ include?", back: "DNA replication, mutation and repair, transcription, RNA processing, translation, gene regulation, and how these processes affect inherited traits.", source: "Designer Genes forum discussion" },
  { id: "dg-145", category: "Question Marathon", front: "Why review both Designer Genes and Heredity materials?", back: "Designer Genes includes the classic and molecular genetics covered by Heredity, then adds deeper molecular, evolutionary, and biotechnology material.", source: "Designer Genes wiki" },
  { id: "dg-146", category: "Inheritance", front: "What is a backcross?", back: "A cross between an offspring and one of its parents or a genetically similar parental genotype; a testcross is a backcross to a homozygous recessive individual.", source: expansionSource },
  { id: "dg-147", category: "Inheritance", front: "A plant with phenotype A is crossed with aa and produces 48 A and 52 a offspring. What is the likely genotype of the parent?", back: "Aa. A testcross giving approximately 1:1 phenotypes indicates the unknown parent produces A and a gametes in similar proportions.", source: expansionSource },
  { id: "dg-148", category: "Inheritance", front: "What is penetrance?", back: "The proportion of individuals with a particular genotype who show the associated phenotype.", source: expansionSource },
  { id: "dg-149", category: "Inheritance", front: "What is variable expressivity?", back: "Variation in the degree or features of a phenotype among individuals with the same disease-associated genotype.", source: expansionSource },
  { id: "dg-150", category: "Inheritance", front: "Why can genotype not always predict phenotype exactly?", back: "Environmental effects, penetrance, expressivity, modifier genes, epistasis, and stochastic development can alter the phenotype.", source: expansionSource },
  { id: "dg-151", category: "Inheritance", front: "What is pleiotropy?", back: "A single gene influences multiple phenotypic traits or biological processes.", source: expansionSource },
  { id: "dg-152", category: "Inheritance", front: "What is polygenic inheritance?", back: "A trait is influenced by alleles at many loci, often producing continuous variation such as height or skin pigmentation.", source: expansionSource },
  { id: "dg-153", category: "Inheritance", front: "Why do polygenic traits often form a bell-shaped distribution?", back: "Many loci with small additive effects create numerous intermediate genotypes, which are more common than extreme combinations.", source: expansionSource },
  { id: "dg-154", category: "Inheritance", front: "What is a threshold trait?", back: "A phenotype that appears when an underlying liability, influenced by multiple genes and environment, exceeds a threshold.", source: expansionSource },
  { id: "dg-155", category: "Inheritance", front: "In an AaBb x AaBb cross, what is the probability of aabb?", back: "1/16, because the probability of aa is 1/4 and the probability of bb is 1/4; multiply independent probabilities.", source: expansionSource },
  { id: "dg-156", category: "Inheritance", front: "In AaBb x AaBb, what is the probability of at least one dominant phenotype at both loci?", back: "9/16. The probability of A_ is 3/4 and of B_ is 3/4, so (3/4)(3/4) = 9/16.", source: expansionSource },
  { id: "dg-157", category: "Inheritance", front: "A carrier mother for an X-linked recessive allele has children with an unaffected father. What is the probability that a randomly selected child is affected?", back: "1/4 overall: half the children are sons and half of sons inherit the allele, assuming equal sex probability and no viability differences.", source: expansionSource },
  { id: "dg-158", category: "Inheritance", front: "What is maternal inheritance?", back: "Inheritance of genetic material, commonly mitochondrial DNA, through the egg cytoplasm; affected mothers can transmit it to offspring, whereas fathers usually do not.", source: expansionSource },
  { id: "dg-159", category: "Inheritance", front: "Why are mitochondrial traits often maternally inherited?", back: "The egg contributes most of the zygote's cytoplasm and mitochondria; sperm mitochondria are generally not retained in the embryo.", source: expansionSource },
  { id: "dg-160", category: "Inheritance", front: "What is genomic imprinting?", back: "Parent-of-origin-specific gene expression caused by epigenetic marks established in the germ line.", source: expansionSource },
  { id: "dg-161", category: "Inheritance", front: "What is anticipation?", back: "A genetic condition appears at younger ages or with increasing severity in successive generations, often associated with repeat expansion.", source: expansionSource },
  { id: "dg-162", category: "Inheritance", front: "What is a complementation test?", back: "A cross used to determine whether recessive mutations causing similar phenotypes are in the same gene: wild-type offspring suggest different genes.", source: expansionSource },
  { id: "dg-163", category: "Inheritance", front: "What is a suppressor mutation?", back: "A second mutation that reduces or eliminates the phenotypic effect of an earlier mutation.", source: expansionSource },
  { id: "dg-164", category: "Inheritance", front: "What is a modifier gene?", back: "A gene whose product changes the expression or severity of a phenotype produced by another gene.", source: expansionSource },
  { id: "dg-165", category: "Inheritance", front: "Why can a lethal recessive allele appear in a 2:1 rather than 3:1 ratio among living offspring?", back: "The homozygous recessive class dies, leaving two heterozygous survivors for every one homozygous dominant survivor.", source: expansionSource },
  { id: "dg-166", category: "DNA", front: "What is the difference between a chromosome, chromatid, and homolog?", back: "A chromosome is a DNA-protein unit; a chromatid is one copy after replication; homologs are the maternal and paternal versions of the same chromosome.", source: expansionSource },
  { id: "dg-167", category: "DNA", front: "What is a karyotype used to detect?", back: "Large-scale chromosome number or structure abnormalities, such as trisomy, monosomy, or major deletions and translocations.", source: expansionSource },
  { id: "dg-168", category: "DNA", front: "What is a locus?", back: "The physical position of a gene or other sequence on a chromosome.", source: expansionSource },
  { id: "dg-169", category: "DNA", front: "What is a haplotype?", back: "A set of alleles or sequence variants at nearby loci that tend to be inherited together on one chromosome.", source: expansionSource },
  { id: "dg-170", category: "DNA", front: "Why are microsatellites useful genetic markers?", back: "Short tandem repeats vary in copy number among individuals and can be genotyped to track inheritance or compare samples.", source: expansionSource },
  { id: "dg-171", category: "DNA", front: "What is an insertion-deletion polymorphism?", back: "A common DNA variation in which a short sequence is present in one allele and absent in another.", source: expansionSource },
  { id: "dg-172", category: "DNA", front: "What is copy-number variation?", back: "A genomic region present in different copy numbers among individuals because of deletion, duplication, or other structural variation.", source: expansionSource },
  { id: "dg-173", category: "DNA", front: "What is a transposable element?", back: "A DNA sequence capable of moving to a new genomic location, sometimes altering gene function or regulation.", source: expansionSource },
  { id: "dg-174", category: "DNA", front: "What is a transposase?", back: "An enzyme encoded by some transposable elements that catalyzes their excision, integration, or movement.", source: expansionSource },
  { id: "dg-175", category: "DNA", front: "Why are repetitive sequences difficult to assemble from short sequencing reads?", back: "Reads from different repeat copies can look identical, so their genomic location and copy number may be ambiguous.", source: expansionSource },
  { id: "dg-176", category: "DNA", front: "What is a DNA polymorphism?", back: "A heritable sequence variation occurring in a population at appreciable frequency; it may be neutral or affect phenotype.", source: expansionSource },
  { id: "dg-177", category: "DNA", front: "What is the relationship between a gene and an allele?", back: "A gene is a functional genomic unit or locus; an allele is one of the alternative sequence forms found at that locus.", source: expansionSource },
  { id: "dg-178", category: "DNA", front: "Why does DNA polymerase need a primer?", back: "It extends an existing 3' hydroxyl group but cannot start a new strand de novo.", source: expansionSource },
  { id: "dg-179", category: "DNA", front: "What is the replication fork?", back: "The Y-shaped region where parental DNA strands separate and new complementary strands are synthesized.", source: expansionSource },
  { id: "dg-180", category: "DNA", front: "What does topoisomerase do during replication?", back: "It relieves torsional strain and supercoiling ahead of the replication fork by transiently cutting and resealing DNA.", source: expansionSource },
  { id: "dg-181", category: "DNA", front: "What is the role of single-strand binding protein?", back: "It stabilizes separated DNA strands and prevents them from reannealing or forming secondary structures.", source: expansionSource },
  { id: "dg-182", category: "DNA", front: "Why is the lagging strand synthesized discontinuously?", back: "DNA polymerase works only 5' to 3', while the antiparallel template requires repeated primers and Okazaki fragments.", source: expansionSource },
  { id: "dg-183", category: "DNA", front: "What is proofreading by DNA polymerase?", back: "Removal of a recently added mismatched nucleotide, usually through 3' to 5' exonuclease activity, before synthesis continues.", source: expansionSource },
  { id: "dg-184", category: "DNA", front: "What is a double-strand break?", back: "DNA damage in which both complementary strands are broken; inaccurate repair can cause deletions, inversions, or translocations.", source: expansionSource },
  { id: "dg-185", category: "DNA", front: "Homologous recombination versus nonhomologous end joining", back: "Homologous recombination uses a matching template for accurate repair; nonhomologous end joining directly joins ends and can introduce small errors.", source: expansionSource },
  { id: "dg-186", category: "DNA", front: "A coding DNA strand reads 5'-ATG GAA TGA-3'. What mRNA sequence is produced?", back: "5'-AUG GAA UGA-3'. The coding strand matches mRNA except that RNA uses uracil instead of thymine.", source: expansionSource },
  { id: "dg-187", category: "DNA", front: "A template DNA strand is 3'-TAC CCT ATT-5'. What peptide is encoded?", back: "The mRNA is 5'-AUG GGA UAA-3', which encodes methionine-glycine followed by a stop signal.", source: expansionSource },
  { id: "dg-188", category: "DNA", front: "If a double-stranded DNA sample is 30% adenine, what percentage is cytosine?", back: "20%. T is 30%, leaving 40% for G and C; because G = C, each is 20%.", source: expansionSource },
  { id: "dg-189", category: "DNA", front: "What is the effect of a transition compared with a transversion?", back: "A transition substitutes within the same base class, while a transversion exchanges a purine and pyrimidine; either can alter coding or regulation.", source: expansionSource },
  { id: "dg-190", category: "RNA", front: "What is RNA polymerase II's major product in eukaryotes?", back: "It transcribes most protein-coding genes into precursor mRNA, as well as some other RNAs.", source: expansionSource },
  { id: "dg-191", category: "RNA", front: "What is the template strand?", back: "The DNA strand read 3' to 5' by RNA polymerase so a complementary RNA strand can be synthesized 5' to 3'.", source: expansionSource },
  { id: "dg-192", category: "RNA", front: "What is the coding strand?", back: "The DNA strand with the same sequence as the RNA transcript except that DNA has thymine where RNA has uracil.", source: expansionSource },
  { id: "dg-193", category: "RNA", front: "What is a 5' cap?", back: "A modified guanine added to eukaryotic pre-mRNA that supports export, stability, and ribosome recruitment.", source: expansionSource },
  { id: "dg-194", category: "RNA", front: "What is a poly-A tail?", back: "A stretch of adenines added to the 3' end of many eukaryotic mRNAs that improves stability, export, and translation efficiency.", source: expansionSource },
  { id: "dg-195", category: "RNA", front: "What is RNA splicing?", back: "Removal of introns and joining of exons from a precursor RNA by the spliceosome or related machinery.", source: expansionSource },
  { id: "dg-196", category: "RNA", front: "What is a splice-site mutation?", back: "A sequence change at an intron-exon boundary that can cause incorrect RNA processing and an abnormal protein.", source: expansionSource },
  { id: "dg-197", category: "RNA", front: "What is wobble base pairing?", back: "Flexible pairing at the third codon position that allows one tRNA to recognize multiple synonymous codons.", source: expansionSource },
  { id: "dg-198", category: "RNA", front: "Why are the genetic code's degeneracy and specificity compatible?", back: "Several codons can specify one amino acid, but each codon has one meaning in a given translation system, aside from defined exceptions.", source: expansionSource },
  { id: "dg-199", category: "RNA", front: "What is a polyribosome?", back: "A group of ribosomes translating the same mRNA simultaneously, increasing protein production from one transcript.", source: expansionSource },
  { id: "dg-200", category: "RNA", front: "What is a signal peptide?", back: "An N-terminal sequence that directs a newly synthesized protein to the endoplasmic reticulum or another cellular destination.", source: expansionSource },
  { id: "dg-201", category: "RNA", front: "What is nonsense-mediated mRNA decay?", back: "A quality-control pathway that detects transcripts with premature stop codons and promotes their degradation.", source: expansionSource },
  { id: "dg-202", category: "Gene Expression", front: "What is an enhancer?", back: "A regulatory DNA element that can increase transcription when bound by activator proteins, often at a distance from the promoter.", source: expansionSource },
  { id: "dg-203", category: "Gene Expression", front: "What is a silencer?", back: "A regulatory DNA element that decreases transcription when bound by repressors or associated regulatory complexes.", source: expansionSource },
  { id: "dg-204", category: "Gene Expression", front: "What is combinatorial gene regulation?", back: "A gene's expression depends on the particular combination of activators, repressors, chromatin state, and signaling inputs present.", source: expansionSource },
  { id: "dg-205", category: "Gene Expression", front: "Why can the same genome produce different cell types?", back: "Different cells activate and silence different genes, producing distinct proteins and regulatory states from the same DNA.", source: expansionSource },
  { id: "dg-206", category: "Gene Expression", front: "What is an epigenome?", back: "The collection of chemical marks and chromatin states that influence gene activity without changing the underlying DNA sequence.", source: expansionSource },
  { id: "dg-207", category: "Gene Expression", front: "What is genomic imprint erasure and resetting?", back: "Germ cells erase inherited imprint marks and establish sex-specific marks that can be transmitted to the next generation.", source: expansionSource },
  { id: "dg-208", category: "Gene Expression", front: "What is X-chromosome inactivation?", back: "Early in female mammalian development, one X chromosome in each cell is largely silenced to balance X-linked gene dosage.", source: expansionSource },
  { id: "dg-209", category: "Gene Expression", front: "What is a Barr body?", back: "The condensed, largely inactive X chromosome visible in many somatic cells of an individual with more than one X chromosome.", source: expansionSource },
  { id: "dg-210", category: "Gene Expression", front: "What is dosage compensation?", back: "A mechanism that equalizes expression of genes on sex chromosomes between individuals with different sex-chromosome complements.", source: expansionSource },
  { id: "dg-211", category: "Gene Expression", front: "What is quorum sensing?", back: "Cell-density-dependent communication in which microorganisms use secreted signals to coordinate gene expression.", source: expansionSource },
  { id: "dg-212", category: "Gene Expression", front: "How does a steroid hormone commonly alter gene expression?", back: "Because it can cross the membrane, it binds an intracellular receptor; the hormone-receptor complex binds DNA regulatory sites and changes transcription.", source: expansionSource },
  { id: "dg-213", category: "Gene Expression", front: "What is signal transduction?", back: "The conversion of an extracellular signal into intracellular molecular changes that alter cell behavior or gene expression.", source: expansionSource },
  { id: "dg-214", category: "Gene Expression", front: "What is a second messenger?", back: "A small intracellular signaling molecule, such as cAMP or Ca2+, that relays and amplifies a receptor signal.", source: expansionSource },
  { id: "dg-215", category: "Gene Expression", front: "What is a constitutively expressed gene?", back: "A gene expressed continually or at a relatively constant baseline because its product is needed routinely.", source: expansionSource },
  { id: "dg-216", category: "Gene Expression", front: "What is negative inducible regulation in bacteria?", back: "A repressor normally blocks transcription, but an inducer binds the repressor and prevents it from binding the operator.", source: expansionSource },
  { id: "dg-217", category: "Gene Expression", front: "What is positive inducible regulation?", back: "An activator is needed for efficient transcription and becomes active when an inducer or signal is present.", source: expansionSource },
  { id: "dg-218", category: "Gene Expression", front: "Why does glucose repress the lac operon when lactose is present?", back: "Low glucose raises cAMP, allowing CAP activation; high glucose keeps cAMP low, so CAP does not strongly activate lac transcription.", source: expansionSource },
  { id: "dg-219", category: "Gene Expression", front: "What is attenuation in the trp operon?", back: "A coupled transcription-translation mechanism in which a leader RNA structure influences whether transcription terminates in response to tryptophan availability.", source: expansionSource },
  { id: "dg-220", category: "Gene Expression", front: "What is a homeobox gene?", back: "A gene encoding a transcription factor with a homeodomain that helps specify body-plan development and cell fates.", source: expansionSource },
  { id: "dg-221", category: "Gene Expression", front: "What is a master regulator?", back: "A regulatory gene whose product initiates a network of gene expression that drives a developmental or cellular program.", source: expansionSource },
  { id: "dg-222", category: "Gene Expression", front: "What is a reporter gene assay?", back: "An experiment that links a regulatory DNA sequence to an easily measured gene product to test transcriptional activity.", source: expansionSource },
  { id: "dg-223", category: "Gene Expression", front: "A promoter mutation reduces mRNA but leaves the protein sequence unchanged. What level is affected?", back: "Transcriptional regulation: the altered promoter changes how often RNA polymerase initiates, not the amino-acid sequence.", source: expansionSource },
  { id: "dg-224", category: "Cell Division", front: "What is synapsis?", back: "Pairing of homologous chromosomes during prophase I of meiosis, forming structures in which crossing over can occur.", source: expansionSource },
  { id: "dg-225", category: "Cell Division", front: "What is a tetrad?", back: "The paired homologous chromosomes in meiosis I, containing four chromatids.", source: expansionSource },
  { id: "dg-226", category: "Cell Division", front: "Why does meiosis reduce chromosome number?", back: "Homologous chromosomes separate in meiosis I without a preceding second round of DNA replication, producing haploid cells.", source: expansionSource },
  { id: "dg-227", category: "Cell Division", front: "What is the difference between homologous chromosomes and sister chromatids?", back: "Homologs carry the same genes but may have different alleles; sister chromatids are nearly identical copies made during replication.", source: expansionSource },
  { id: "dg-228", category: "Cell Division", front: "What is synaptonemal complex function?", back: "It helps align homologous chromosomes during meiotic synapsis and supports recombination between them.", source: expansionSource },
  { id: "dg-229", category: "Cell Division", front: "How many genetically distinct gametes can independent assortment alone produce in a human?", back: "2^23, or about 8.4 million chromosome combinations, before considering crossing over.", source: expansionSource },
  { id: "dg-230", category: "Cell Division", front: "What is uniparental disomy?", back: "Inheritance of both copies of a chromosome or chromosome region from one parent and none from the other.", source: expansionSource },
  { id: "dg-231", category: "Cell Division", front: "What is mosaicism?", back: "The presence of two or more genetically distinct cell populations derived from one zygote.", source: expansionSource },
  { id: "dg-232", category: "Cell Division", front: "Why can mosaicism make a chromosome disorder variable?", back: "The proportion and distribution of abnormal cells can differ among tissues, changing severity and clinical features.", source: expansionSource },
  { id: "dg-233", category: "Cell Division", front: "What is cytokinesis?", back: "Division of the cytoplasm after nuclear division, producing separate daughter cells.", source: expansionSource },
  { id: "dg-234", category: "Population Genetics", front: "What is a population's gene pool?", back: "All alleles present in the interbreeding population at a given time.", source: expansionSource },
  { id: "dg-235", category: "Population Genetics", front: "What is relative fitness?", back: "An individual's or genotype's contribution of viable, reproducing offspring to the next generation compared with alternatives.", source: expansionSource },
  { id: "dg-236", category: "Population Genetics", front: "What is directional selection?", back: "Selection that favors one extreme phenotype and shifts the population mean toward that extreme.", source: expansionSource },
  { id: "dg-237", category: "Population Genetics", front: "What is stabilizing selection?", back: "Selection that favors intermediate phenotypes and reduces the frequency of extremes.", source: expansionSource },
  { id: "dg-238", category: "Population Genetics", front: "What is disruptive selection?", back: "Selection that favors both extremes over intermediate phenotypes and can increase variation or promote divergence.", source: expansionSource },
  { id: "dg-239", category: "Population Genetics", front: "What is heterozygote advantage?", back: "A condition in which the heterozygote has greater fitness than either homozygote, maintaining alleles in a population.", source: expansionSource },
  { id: "dg-240", category: "Population Genetics", front: "What is frequency-dependent selection?", back: "Selection whose strength or direction depends on how common or rare a phenotype is.", source: expansionSource },
  { id: "dg-241", category: "Population Genetics", front: "A recessive phenotype has frequency q^2 = 0.09 in a Hardy-Weinberg population. What is the carrier frequency?", back: "q = 0.3, p = 0.7, so 2pq = 2(0.7)(0.3) = 0.42, or 42%.", source: expansionSource },
  { id: "dg-242", category: "Population Genetics", front: "Why does migration often reduce differences between populations?", back: "Gene flow introduces alleles into recipient populations and tends to homogenize allele frequencies.", source: expansionSource },
  { id: "dg-243", category: "Population Genetics", front: "What is genetic hitchhiking?", back: "A neutral or mildly selected allele changes frequency because it is physically linked to an allele under strong selection.", source: expansionSource },
  { id: "dg-244", category: "Population Genetics", front: "What is linkage disequilibrium?", back: "Nonrandom association of alleles at different loci relative to the association expected from their individual frequencies.", source: expansionSource },
  { id: "dg-245", category: "Population Genetics", front: "How does recombination affect linkage disequilibrium?", back: "Recombination breaks up allele combinations, generally reducing linkage disequilibrium over generations unless selection or other forces maintain it.", source: expansionSource },
  { id: "dg-246", category: "Evolution", front: "What is a molecular clock?", back: "An approach that uses approximately regular accumulation of sequence differences to estimate divergence times, calibrated with known dates.", source: expansionSource },
  { id: "dg-247", category: "Evolution", front: "What is a neutral mutation?", back: "A sequence change with no measurable effect on fitness in the relevant environment.", source: expansionSource },
  { id: "dg-248", category: "Evolution", front: "What is a molecular homology?", back: "Similarity in DNA, RNA, or protein sequence due to inheritance from a common ancestor.", source: expansionSource },
  { id: "dg-249", category: "Evolution", front: "What is a derived character?", back: "A trait that evolved in a lineage relative to its ancestral condition; shared derived characters help define clades.", source: expansionSource },
  { id: "dg-250", category: "Evolution", front: "What is an outgroup used for in cladistics?", back: "A related lineage outside the group of interest that helps identify ancestral versus derived character states.", source: expansionSource },
  { id: "dg-251", category: "Biotechnology", front: "What are the essential features of a cloning plasmid?", back: "An origin of replication, a selectable marker, and a region where foreign DNA can be inserted; expression vectors also need regulatory sequences.", source: expansionSource },
  { id: "dg-252", category: "Biotechnology", front: "What is a selectable marker?", back: "A gene that lets researchers identify cells carrying a vector, often by conferring antibiotic resistance or another growth phenotype.", source: expansionSource },
  { id: "dg-253", category: "Biotechnology", front: "Why is an antibiotic-resistance control needed in a transformation experiment?", back: "Growth on selective medium tests whether cells received and express the vector marker; controls reveal whether selection or transformation worked.", source: expansionSource },
  { id: "dg-254", category: "Biotechnology", front: "What is bacterial transformation?", back: "The uptake and expression of external DNA by a bacterial cell.", source: expansionSource },
  { id: "dg-255", category: "Biotechnology", front: "What is electroporation?", back: "A method that uses a brief electric pulse to create temporary membrane pores through which DNA can enter cells.", source: expansionSource },
  { id: "dg-256", category: "Biotechnology", front: "What is reverse transcription PCR?", back: "RT-PCR converts RNA to complementary DNA with reverse transcriptase, then amplifies the cDNA by PCR to detect or quantify transcripts.", source: expansionSource },
  { id: "dg-257", category: "Biotechnology", front: "What is quantitative PCR?", back: "PCR that monitors fluorescence during amplification to estimate the starting amount of a target nucleic acid.", source: expansionSource },
  { id: "dg-258", category: "Biotechnology", front: "What does a lower qPCR Ct value usually indicate?", back: "More starting target nucleic acid, because fewer amplification cycles are needed to cross the fluorescence threshold.", source: expansionSource },
  { id: "dg-259", category: "Biotechnology", front: "What is Sanger sequencing based on?", back: "Chain termination by fluorescently labeled dideoxynucleotides that lack a 3' hydroxyl, followed by fragment-size separation and readout.", source: expansionSource },
  { id: "dg-260", category: "Biotechnology", front: "What is next-generation sequencing?", back: "High-throughput sequencing that reads many DNA fragments in parallel, allowing large numbers of bases or samples to be analyzed.", source: expansionSource },
  { id: "dg-261", category: "Biotechnology", front: "What is a reference genome?", back: "A representative assembled sequence used as a coordinate framework for aligning and interpreting sample reads.", source: expansionSource },
  { id: "dg-262", category: "Biotechnology", front: "Why are read depth and coverage important in sequencing?", back: "Higher coverage increases confidence that a base call or variant is supported and helps detect variants present in only a fraction of cells.", source: expansionSource },
  { id: "dg-263", category: "Biotechnology", front: "What is an allele-specific PCR assay?", back: "PCR designed so a primer matches one allele at its 3' end, producing amplification preferentially when that allele is present.", source: expansionSource },
  { id: "dg-264", category: "Biotechnology", front: "What is a DNA microarray?", back: "A surface containing many known probes used to measure complementary nucleic acids or genotype many loci simultaneously.", source: expansionSource },
  { id: "dg-265", category: "Biotechnology", front: "What is Western blotting used to measure?", back: "Specific proteins separated by size and detected with antibodies.", source: expansionSource },
  { id: "dg-266", category: "Biotechnology", front: "What is an ELISA?", back: "An enzyme-linked immunoassay that uses specific antibody-antigen binding and a color or light signal to detect or quantify a target.", source: expansionSource },
  { id: "dg-267", category: "Biotechnology", front: "Why does a no-template PCR control matter?", back: "It should lack amplification; a band or signal suggests contamination or nonspecific artifact and weakens sample conclusions.", source: expansionSource },
  { id: "dg-268", category: "Biotechnology", front: "What is a guide RNA's role in CRISPR-Cas9?", back: "It base-pairs with the target DNA sequence and positions Cas9 near the matching site, where the nuclease makes a double-strand break.", source: expansionSource },
  { id: "dg-269", category: "Biotechnology", front: "What is a CRISPR off-target effect?", back: "Unintended cutting or editing at a sequence similar to the intended target.", source: expansionSource },
  { id: "dg-270", category: "Biotechnology", front: "What is CRISPR base editing?", back: "A strategy that changes one base to another using a targeted deaminase without making a conventional double-strand break.", source: expansionSource },
  { id: "dg-271", category: "Biotechnology", front: "What is gene therapy?", back: "Treatment that modifies genetic material or its expression to address a disease, for example by adding, silencing, or editing a gene.", source: expansionSource },
  { id: "dg-272", category: "Biotechnology", front: "What is a viral vector?", back: "A modified virus used to deliver genetic material to target cells while reducing its ability to cause disease.", source: expansionSource },
  { id: "dg-273", category: "Biotechnology", front: "What is RNA interference?", back: "Sequence-specific gene silencing in which small RNAs guide a protein complex to degrade target mRNA or inhibit its translation.", source: expansionSource },
  { id: "dg-274", category: "Biotechnology", front: "A gel band is 2.5 cm from the well while 500 bp and 1000 bp ladder bands are 3.5 cm and 2.0 cm away. What size is the sample approximately?", back: "Between 500 and 1000 bp, closer to 1000 bp; migration is logarithmically related to size, so an exact value requires a calibration plot.", source: expansionSource },
  { id: "dg-275", category: "Biotechnology", front: "Why must PCR primers face inward?", back: "DNA polymerases extend from each primer toward the other, so inward-facing primers define and exponentially amplify the intervening region.", source: expansionSource },
  { id: "dg-276", category: "Biotechnology", front: "What is a restriction-site polymorphism?", back: "A sequence variation that creates or removes a restriction-enzyme recognition site, changing the fragment pattern after digestion.", source: expansionSource },
  { id: "dg-277", category: "Biotechnology", front: "What is genetic fingerprinting?", back: "Comparing variable DNA markers, often short tandem repeats, to assess whether samples share a likely biological source.", source: expansionSource },
  { id: "dg-278", category: "Biotechnology", front: "Why is a DNA match not automatically proof of guilt?", back: "A match addresses sample origin or relatedness, but collection quality, contamination, population statistics, chain of custody, and other evidence also matter.", source: "Designer Genes forum discussion; OpenStax Biology 2e" },
  { id: "dg-279", category: "Biotechnology", front: "What is recombinant protein expression?", back: "Using a host cell containing an engineered gene to produce a desired protein, which can then be harvested and purified.", source: expansionSource },
  { id: "dg-280", category: "Biotechnology", front: "Why might a eukaryotic protein be difficult to produce in bacteria?", back: "Bacteria may lack eukaryotic intron processing, folding, glycosylation, or other post-translational machinery needed for a functional protein.", source: expansionSource },
  { id: "dg-281", category: "Question Marathon", front: "A mutation changes one codon but the amino acid remains the same. What must be checked before calling it harmless?", back: "Check splicing, mRNA stability, translation efficiency, protein folding, regulation, and the biological context; a synonymous change can still have effects.", source: "Designer Genes Question Marathon; OpenStax Biology 2e" },
  { id: "dg-282", category: "Question Marathon", front: "A pedigree shows unaffected parents with an affected son and daughter, and the trait skips generations. Which model is a strong first hypothesis?", back: "Autosomal recessive inheritance, while checking consanguinity, penetrance, phenocopies, and whether the pedigree symbols are complete.", source: "Designer Genes Question Marathon; OpenStax Biology 2e" },
  { id: "dg-283", category: "Question Marathon", front: "A population has 16% individuals with a recessive phenotype under Hardy-Weinberg assumptions. What fraction is heterozygous?", back: "q = 0.4 and p = 0.6, so 2pq = 0.48, or 48%.", source: "Designer Genes Question Marathon; OpenStax Biology 2e" },
  { id: "dg-284", category: "Question Marathon", front: "A PCR sample has no band, but the positive control also has no band. Can the sample be called negative?", back: "No. The failed positive control indicates the assay may not have worked; troubleshoot primers, template, reagents, cycling, and loading first.", source: "Designer Genes Question Marathon; OpenStax Biology 2e" },
  { id: "dg-285", category: "Question Marathon", front: "A heterozygous individual for two linked genes produces 42% parental gametes of one type, 42% of the other, and 8% of each recombinant type. What is the map distance?", back: "Recombination frequency is 16%, so the loci are approximately 16 map units apart.", source: "Designer Genes Question Marathon; OpenStax Biology 2e" },
  { id: "dg-286", category: "Question Marathon", front: "Why can a beneficial allele remain rare for many generations?", back: "Selection may be weak, the allele may be recessive, populations may be large, gene flow may oppose it, or drift and chance may delay its spread.", source: "Designer Genes Question Marathon; OpenStax Biology 2e" },
  { id: "dg-287", category: "Question Marathon", front: "A restriction digest produces fragments of 2.0 kb and 3.0 kb from one allele but a single 5.0 kb fragment from another. What explains the difference?", back: "A sequence variation likely creates or removes the restriction site, producing a restriction fragment length polymorphism.", source: "Designer Genes Question Marathon; OpenStax Biology 2e" },
  { id: "dg-288", category: "Question Marathon", front: "Why should a negative result in a genetic test be reported with the assay's limits?", back: "The test may not detect every variant, region, mosaic fraction, or mechanism; a negative result means no target detected under those conditions.", source: "Designer Genes forum discussion; OpenStax Biology 2e" },
  { id: "dg-289", category: "Question Marathon", front: "What evidence distinguishes natural selection from genetic drift in a small population?", back: "A consistent association between a heritable trait and reproductive success supports selection; random frequency changes unrelated to fitness support drift.", source: "Designer Genes Question Marathon; OpenStax Biology 2e" },
  { id: "dg-290", category: "Question Marathon", front: "What is the most defensible workflow for a multi-step Designer Genes data problem?", back: "Define the biological model, label alleles or sequences, track units and strand direction, calculate with stated assumptions, inspect controls, and test whether the result is biologically plausible.", source: "Designer Genes forum discussion; OpenStax Biology 2e" },
  { id: "dg-291", category: "Inheritance", front: "A testcross produces 48 dominant-phenotype and 52 recessive-phenotype offspring. What genotype is most likely for the tested parent?", back: "Heterozygous, because Aa x aa is expected to produce a roughly 1:1 phenotype ratio under complete dominance.", source },
  { id: "dg-292", category: "Inheritance", front: "What is the probability that AaBb produces an AB gamete?", back: "One-half A times one-half B = one-fourth, assuming the loci assort independently.", source },
  { id: "dg-293", category: "Inheritance", front: "What is the probability that two Aa parents have an aa child and then an AA child?", back: "Multiply independent birth probabilities: 1/4 x 1/4 = 1/16, assuming the same parental genotypes for both births.", source },
  { id: "dg-294", category: "Inheritance", front: "A woman with type AB blood and a man with type O blood have children. Which ABO phenotypes are possible?", back: "Type A (IAi) and type B (IBi) are possible; type AB and type O are not possible from these parental alleles.", source },
  { id: "dg-295", category: "Inheritance", front: "Why can a pedigree fail to show a classic Mendelian pattern?", back: "Small family size, incomplete penetrance, variable expressivity, new mutation, adoption, inaccurate records, or environmental effects can obscure the pattern.", source },
  { id: "dg-296", category: "Inheritance", front: "How is penetrance measured?", back: "The proportion of individuals with a particular genotype who display the associated phenotype.", source },
  { id: "dg-297", category: "Inheritance", front: "How is variable expressivity recognized?", back: "Differences in the degree or features of a phenotype among individuals with the same genotype.", source },
  { id: "dg-298", category: "Inheritance", front: "An affected father transmits a trait to all daughters but no sons. What inheritance pattern is suggested?", back: "X-linked dominant inheritance is a strong possibility because fathers give their X chromosome to daughters and their Y chromosome to sons.", source },
  { id: "dg-299", category: "Inheritance", front: "Why does a father not pass an X-linked allele to his sons?", back: "A son receives the father's Y chromosome, not his X chromosome; the son receives his X chromosome from the mother.", source },
  { id: "dg-300", category: "Inheritance", front: "How does parent-of-origin imprinting affect expression?", back: "Parent-of-origin-specific gene expression in which an allele's activity depends on whether it was inherited from the mother or father.", source },
  { id: "dg-301", category: "Population Genetics", front: "What conditions define Hardy-Weinberg equilibrium?", back: "A very large population, random mating, no mutation, no migration, and no natural selection; under these assumptions allele frequencies remain constant.", source },
  { id: "dg-302", category: "Population Genetics", front: "How are allele frequencies represented for a two-allele locus?", back: "If alleles have frequencies p and q, then p + q = 1; under Hardy-Weinberg, genotype frequencies are p^2 + 2pq + q^2 = 1.", source },
  { id: "dg-303", category: "Population Genetics", front: "A recessive phenotype occurs in 9% of a Hardy-Weinberg population. What are p and q?", back: "q^2 = 0.09, so q = 0.30 and p = 0.70.", source },
  { id: "dg-304", category: "Population Genetics", front: "Using p = 0.70 and q = 0.30, what fraction is heterozygous?", back: "2pq = 2(0.70)(0.30) = 0.42, or 42%.", source },
  { id: "dg-305", category: "Population Genetics", front: "Why can a recessive disease allele remain common when affected individuals are uncommon?", back: "Most copies can be carried in unaffected heterozygotes, so selection against affected homozygotes removes only part of the allele pool each generation.", source },
  { id: "dg-306", category: "Population Genetics", front: "What random process can change allele frequencies in small populations?", back: "A random change in allele frequencies caused by sampling effects, especially strong in small populations.", source },
  { id: "dg-307", category: "Population Genetics", front: "Founder effect versus bottleneck effect", back: "Founder effect follows establishment by a small subset of a source population; bottleneck effect follows a sharp reduction in an existing population.", source },
  { id: "dg-308", category: "Population Genetics", front: "How does gene flow affect populations?", back: "Movement of alleles between populations can introduce variation, change allele frequencies, and reduce genetic differences between populations.", source },
  { id: "dg-309", category: "Population Genetics", front: "How is relative fitness compared among genotypes?", back: "A measure of an individual's or genotype's contribution of viable, reproductive offspring compared with alternatives in that environment.", source },
  { id: "dg-310", category: "Population Genetics", front: "Why is natural selection described as acting on phenotypes but changing genotypes?", back: "Selection directly favors observable traits affecting survival or reproduction, while the inherited alleles underlying those traits change in frequency.", source },
  { id: "dg-311", category: "Population Genetics", front: "What is balancing selection?", back: "Selection that maintains multiple alleles in a population, for example through heterozygote advantage or changing environmental pressures.", source },
  { id: "dg-312", category: "Population Genetics", front: "What is sexual selection?", back: "Selection arising from differences in mating success, such as mate choice or competition for mates, rather than survival alone.", source },
  { id: "dg-313", category: "Population Genetics", front: "How can genetic drift reduce variation?", back: "Random sampling can eliminate alleles from a small population, especially after a bottleneck or founder event.", source },
  { id: "dg-314", category: "Evolution", front: "What is a homologous structure?", back: "A structure inherited from a common ancestor that may have different functions in descendant lineages.", source },
  { id: "dg-315", category: "Evolution", front: "What process independently produces similar traits in separate lineages?", back: "Independent evolution of similar traits in lineages that do not share the trait from a recent common ancestor, often under similar selective pressures.", source },
  { id: "dg-316", category: "DNA", front: "Why must DNA polymerase use a primer?", back: "It can extend an existing strand by adding to a free 3' hydroxyl but cannot begin a new strand from nothing.", source },
  { id: "dg-317", category: "DNA", front: "What is the template strand in transcription?", back: "The DNA strand read by RNA polymerase 3' to 5' to synthesize a complementary RNA strand 5' to 3'.", source },
  { id: "dg-318", category: "DNA", front: "A DNA template strand reads 3'-TAC GGA-5'. What mRNA sequence is produced?", back: "5'-AUG CCU-3', because RNA bases pair complementarily and the transcript is synthesized 5' to 3'.", source },
  { id: "dg-319", category: "DNA", front: "What is proofreading during DNA replication?", back: "Polymerase-mediated checking and removal of some incorrectly paired nucleotides before synthesis continues.", source },
  { id: "dg-320", category: "DNA", front: "Why does a replication fork have leading and lagging strands?", back: "The two DNA templates are antiparallel, but polymerases synthesize only 5' to 3', forcing discontinuous synthesis on one template.", source },
  { id: "dg-321", category: "DNA", front: "How does mismatch repair correct replication errors?", back: "A post-replication pathway that recognizes and replaces incorrectly paired bases that escaped polymerase proofreading.", source },
  { id: "dg-322", category: "DNA Repair", front: "What does nucleotide excision repair remove?", back: "A short stretch of damaged DNA containing a bulky distortion, after which the gap is resynthesized and sealed.", source },
  { id: "dg-323", category: "DNA Repair", front: "How does nonhomologous end joining differ from homologous recombination repair?", back: "Nonhomologous end joining joins broken ends without a matching template and can introduce small changes; homologous recombination uses a homologous template for more accurate repair.", source },
  { id: "dg-324", category: "DNA", front: "Why is a frameshift usually more disruptive than a single-base substitution?", back: "An insertion or deletion not divisible by three changes every downstream codon in the reading frame, often producing a premature stop.", source },
  { id: "dg-325", category: "DNA", front: "A codon changes from CUA to CUG. What kind of coding mutation is this?", back: "It is synonymous because both codons specify leucine, although effects on splicing, translation, or regulation should not be assumed absent.", source },
  { id: "dg-326", category: "RNA", front: "What is RNA polymerase's role?", back: "It binds a promoter, locally opens DNA, and polymerizes an RNA transcript using a DNA template.", source },
  { id: "dg-327", category: "RNA", front: "How does a ribosome identify the correct tRNA?", back: "The tRNA anticodon base-pairs with the mRNA codon in the ribosome, following codon direction and wobble rules where applicable.", source },
  { id: "dg-328", category: "RNA", front: "What is the reading frame?", back: "The grouping of an mRNA sequence into consecutive three-base codons beginning at a start codon.", source },
  { id: "dg-329", category: "RNA", front: "An mRNA is 900 nucleotides long including a 60-nucleotide untranslated region and a 30-nucleotide stop-plus-trailing region. How many coding amino-acid codons remain?", back: "(900 - 60 - 30) / 3 = 270 codons in the stated coding region; whether the stop codon contributes an amino acid depends on how the regions were defined.", source },
  { id: "dg-330", category: "RNA", front: "Why does a stop codon not recruit a tRNA?", back: "Release factors recognize the stop codon and trigger release of the completed polypeptide instead of adding another amino acid.", source },
  { id: "dg-331", category: "Gene Expression", front: "Which DNA elements can increase transcription from a distance?", back: "A regulatory DNA sequence that can increase transcription when activator proteins and associated machinery act through it, often from a distance.", source },
  { id: "dg-332", category: "Gene Expression", front: "How can a transcription factor regulate a gene?", back: "By binding a regulatory DNA sequence and recruiting or blocking transcription machinery, changing initiation or chromatin access.", source },
  { id: "dg-333", category: "Gene Expression", front: "What is epigenetic regulation?", back: "Heritable or stable changes in gene activity that do not change the DNA sequence, including DNA methylation and histone modification.", source },
  { id: "dg-334", category: "Gene Expression", front: "How can DNA methylation affect transcription?", back: "Methylation at regulatory regions can reduce transcription by interfering with factor binding or recruiting proteins that compact chromatin.", source },
  { id: "dg-335", category: "Gene Expression", front: "How are bacterial operons organized?", back: "A group of prokaryotic genes controlled by a shared promoter and regulatory region and transcribed as a coordinated unit.", source },
  { id: "dg-336", category: "Gene Expression", front: "What is the difference between an inducible and repressible operon?", back: "An inducible operon is commonly activated when a substrate is present; a repressible operon is commonly turned down when an end product is abundant.", source },
  { id: "dg-337", category: "Gene Expression", front: "Why can one gene produce multiple proteins in eukaryotes?", back: "Alternative promoters, RNA splicing, RNA editing, and post-translational processing can generate distinct products from related transcripts.", source },
  { id: "dg-338", category: "Cell Division", front: "What is the chromosome number after meiosis I?", back: "Each daughter cell is haploid because homologous chromosomes have separated, although each chromosome still consists of two sister chromatids.", source },
  { id: "dg-339", category: "Cell Division", front: "What is the chromosome number after meiosis II?", back: "Each product is haploid with unduplicated chromosomes because sister chromatids have separated.", source },
  { id: "dg-340", category: "Cell Division", front: "How does crossing over create genetic variation?", back: "It exchanges DNA between homologous nonsister chromatids, producing new allele combinations on chromosomes.", source },
  { id: "dg-341", category: "Cell Division", front: "When do homologs pair during meiosis, and why?", back: "Pairing of homologous chromosomes during prophase I of meiosis, forming tetrads that allow crossing over.", source },
  { id: "dg-342", category: "Cell Division", front: "A human gamete has 24 chromosomes. What error could explain this result?", back: "Nondisjunction during meiosis could produce a gamete with n + 1 chromosomes rather than the normal haploid number of 23.", source },
  { id: "dg-343", category: "Cell Division", front: "What is a karyotype used to identify?", back: "The number, size, and gross structure of chromosomes, including some aneuploidies and large rearrangements.", source },
  { id: "dg-344", category: "Cell Division", front: "What is trisomy?", back: "An aneuploid state with three copies of one chromosome instead of the usual two.", source },
  { id: "dg-345", category: "Cell Division", front: "Why does independent assortment increase combinations even without crossing over?", back: "Each homologous pair aligns independently at metaphase I, allowing different maternal and paternal chromosome combinations in gametes.", source },
  { id: "dg-346", category: "Biotechnology", front: "What is the purpose of a DNA ladder in gel electrophoresis?", back: "It provides fragments of known sizes for estimating the sizes of sample bands.", source: expansionSource },
  { id: "dg-347", category: "Biotechnology", front: "Why do smaller DNA fragments migrate farther in an agarose gel?", back: "They pass through the gel matrix more easily under the electric field, while DNA overall moves toward the positive electrode.", source: expansionSource },
  { id: "dg-348", category: "Biotechnology", front: "What does PCR denaturation accomplish?", back: "Heat separates the two DNA strands so primers can bind to single-stranded templates in the next step.", source: expansionSource },
  { id: "dg-349", category: "Biotechnology", front: "What occurs during PCR annealing?", back: "The temperature is lowered so primers hybridize to complementary target sequences; primer sequence and temperature determine specificity.", source: expansionSource },
  { id: "dg-350", category: "Biotechnology", front: "What occurs during PCR extension?", back: "A thermostable DNA polymerase extends each bound primer by adding complementary nucleotides, typically at its optimal temperature.", source: expansionSource },
  { id: "dg-351", category: "Biotechnology", front: "Why does PCR amplify a target exponentially?", back: "Each cycle makes new templates that can be copied in later cycles, so ideal product quantity approximately doubles per cycle.", source: expansionSource },
  { id: "dg-352", category: "Biotechnology", front: "After 10 ideal PCR cycles starting from one target molecule, how many target copies are expected?", back: "Approximately 2^10 = 1,024 copies, recognizing that real reactions plateau and are less efficient than ideal amplification.", source: expansionSource },
  { id: "dg-353", category: "Biotechnology", front: "What is the purpose of a positive PCR control?", back: "It contains a known amplifiable target and confirms that primers, polymerase, cycling, and detection worked.", source: expansionSource },
  { id: "dg-354", category: "Biotechnology", front: "What is a housekeeping gene control in gene-expression analysis?", back: "A reference transcript expected to be relatively stable, used to normalize sample input and technical variation.", source: expansionSource },
  { id: "dg-355", category: "Biotechnology", front: "What does reverse transcriptase do in RT-PCR?", back: "It synthesizes complementary DNA from an RNA template, allowing RNA abundance to be analyzed with PCR.", source: expansionSource },
  { id: "dg-356", category: "Biotechnology", front: "Why is a restriction enzyme useful in recombinant DNA work?", back: "It cuts DNA at a specific recognition sequence, creating fragments or compatible ends that can be analyzed or joined.", source: expansionSource },
  { id: "dg-357", category: "Biotechnology", front: "What is the role of DNA ligase in cloning?", back: "It forms phosphodiester bonds that join compatible DNA ends, sealing an insert into a vector or repairing a backbone.", source: expansionSource },
  { id: "dg-358", category: "Biotechnology", front: "How can a selectable marker identify transformed cells?", back: "A gene that lets researchers identify cells carrying a vector, often by conferring resistance or enabling growth under a selective condition.", source: expansionSource },
  { id: "dg-359", category: "Biotechnology", front: "Why include a guide-sequence control in a CRISPR experiment?", back: "A non-targeting or alternative guide helps distinguish target-specific editing from delivery, toxicity, or general stress effects.", source: expansionSource },
  { id: "dg-360", category: "Biotechnology", front: "How can Sanger sequencing reveal a heterozygous single-base variant?", back: "Overlapping peaks at one position in the chromatogram indicate two bases in the sample, consistent with a heterozygous variant if quality and alignment support it.", source: expansionSource },
  { id: "dg-361", category: "Question Marathon", front: "A heterozygous tall plant is crossed with a short plant and produces 92 tall and 88 short offspring. What should be concluded?", back: "The approximately 1:1 result supports a Tt testcross under complete dominance; it is evidence for the model, not proof that sampling variation is absent.", source: "Designer Genes Question Marathon; OpenStax Biology 2e" },
  { id: "dg-362", category: "Question Marathon", front: "A population has q = 0.2 under Hardy-Weinberg assumptions. What fraction is expected to be homozygous dominant?", back: "p = 0.8, so p^2 = 0.64, or 64%.", source: "Designer Genes Question Marathon; OpenStax Biology 2e" },
  { id: "dg-363", category: "Question Marathon", front: "Two linked genes have 12 recombinant offspring among 100 total. What map distance is estimated?", back: "Recombination frequency is 12%, so the loci are approximately 12 map units apart for this range.", source: "Designer Genes Question Marathon; Campbell Biology" },
  { id: "dg-364", category: "Question Marathon", front: "A mutation changes an amino-acid codon to a stop codon near the gene's beginning. What effect is likely?", back: "A nonsense mutation may produce a severely truncated protein or trigger transcript surveillance, but the actual effect depends on transcript and cellular context.", source: "Designer Genes Question Marathon; OpenStax Biology 2e" },
  { id: "dg-365", category: "Question Marathon", front: "A gel lane shows the expected band in the no-template control. What is the most likely interpretation?", back: "Contamination or nonspecific product is present; sample bands cannot be trusted until the assay is cleaned up and repeated with valid controls.", source: "Designer Genes Question Marathon; OpenStax Biology 2e" },
  { id: "dg-366", category: "Question Marathon", front: "A gene is transcribed in one cell type but not another even though both have the gene. What level of explanation should be tested first?", back: "Cell-specific regulation such as transcription factors, chromatin state, enhancer activity, RNA processing, or transcript stability rather than gene presence alone.", source: "Designer Genes Question Marathon; OpenStax Biology 2e" },
  { id: "dg-367", category: "Question Marathon", front: "Why should a DNA sequence be reported with strand orientation?", back: "The same sequence read on opposite strands has different 5' and 3' direction and complementary bases, which changes primer, template, and codon interpretation.", source: "Designer Genes Question Marathon; Campbell Biology" },
  { id: "dg-368", category: "Question Marathon", front: "A phenotype appears after exposure only in individuals with one genotype. What two explanations should be separated?", back: "A gene-environment interaction may make genotype alter response to exposure, or the genotype may be associated with a confounding factor that actually drives the phenotype.", source: "Designer Genes Question Marathon; OpenStax Biology 2e" },
  { id: "dg-369", category: "Question Marathon", front: "What controls are needed to interpret a gene-editing phenotype?", back: "At minimum include untreated or mock-treated cells, a non-targeting guide control, editing or sequence confirmation, and preferably independent guide or rescue evidence.", source: "Designer Genes forum discussion; OpenStax Biology 2e" },
  { id: "dg-370", category: "Question Marathon", front: "What is the best way to answer an unfamiliar Designer Genes mechanism question?", back: "Identify the level of biology involved, state the relevant inheritance or molecular rule, trace direction and causality step by step, calculate with units, and use controls to limit the conclusion.", source: "Designer Genes forum discussion; OpenStax Biology 2e" },
];
